if (!response.ok) {
  throw new Error(`Request failed with status ${response.status}`);
}

// 1. The browser requests the server's certificate
// 2. The certificate is verified against a certificate authority (CA)
// 3. Client and server agree on a shared session key
// 4. All following data is encrypted with this key
fetch('https://api.example.com/login', { method: 'POST', body: JSON.stringify(credentials) });
// -> the password travels encrypted, unreadable if intercepted
// 5. If the certificate is not recognized (self-signed, expired), the browser blocks the connection by default
fetch('https://self-signed.example.com/data').catch(err => console.error('TLS failure:', err.message));

const socket = new WebSocket('wss://chat.example.com');

socket.onopen = () => socket.send('Hello from the client!');

socket.onmessage = (event) => {
  console.log('Message received:', event.data);
};

socket.onclose = () => console.log('Connection closed');
